INSERT INTO `categories` (`id`,`slug`,`label_en`,`label_cn`,`blurb_en`,`blurb_cn`,`sort_order`) VALUES (1,'chinese_snake','Chinese Snakes','国产蛇类','Native Chinese colubrids and rat snakes — primary colors through high-end morphs.','中国本土游蛇与锦蛇——从原色到高端品系。',1);
INSERT INTO `categories` (`id`,`slug`,`label_en`,`label_cn`,`blurb_en`,`blurb_cn`,`sort_order`) VALUES (2,'venomous','Venomous','毒蛇类','Venomous species for licensed institutions and permitted keepers. Buyer qualification review required.','面向持证机构与许可饲养者的毒蛇类，报价前需通过买家资质审核。',2);
